                    x: idealGrid.x.slice(startIdx, endIdx + 1),
                    y: idealGrid.y.slice(startIdx, endIdx + 1),
                    mode: 'lines',
                    line: { color: '#888888', width: 1 },
                    showlegend: i === 0,
                    name: i === 0 ? 'Ideal Grid' : undefined,
                    hoverinfo: 'skip',
