                                range: [-halfScaleUm, halfScaleUm],
                                showgrid: true,
                                zeroline: true,
                                showticklabels: c === 0,
                                title: c === 0 ? (objectLabels[r] || ('Object ' + (r + 1))) : '',
                                scaleanchor: axisRefX,
